window.__portfolioMountTechnical({"html": "<div id=\"technical-detail\" class=\"legacy-emg-host\"></div>", "scripts": ["(()=>{\n  const host=document.querySelector('#technical-deferred-content .legacy-emg-host');\n  if(!host || host.shadowRoot) return;\n  const root=host.attachShadow({mode:'open'});\n  const style=document.createElement('style');\n  style.textContent=\"\\n    :host {\\n      --bg: #0b0707;\\n      --panel: #100c0c;\\n      --panel-soft: rgba(244, 240, 234, 0.026);\\n      --text: #f4f0ea;\\n      --muted: #aaa39a;\\n      --line: rgba(244, 240, 234, 0.30);\\n      --line-soft: rgba(244, 240, 234, 0.13);\\n      --accent-line: #123a5a;\\n      --accent-text: #6fa0c8;\\n      --paper: #f4f2ed;\\n      --display: \\\"Cormorant Garamond\\\", Georgia, serif;\\n      --sans: \\\"Inter\\\", \\\"Helvetica Neue\\\", Arial, sans-serif;\\n    }\\n\\n    * {\\n      box-sizing: border-box;\\n    }\\n\\n    html {\\n      scroll-behavior: smooth;\\n      background: var(--bg);\\n    }\\n\\n    body {\\n      margin: 0;\\n      min-height: 0;\\n      overflow-x: hidden;\\n      background: var(--bg);\\n      color: var(--text);\\n      font-family: var(--sans);\\n      letter-spacing: 0.02em;\\n      scrollbar-color:\\n        rgba(244, 240, 234, 0.28)\\n        rgba(11, 7, 7, 0.78);\\n      scrollbar-width: thin;\\n    }\\n\\n    *::-webkit-scrollbar {\\n      width: 8px;\\n      height: 8px;\\n    }\\n\\n    *::-webkit-scrollbar-track {\\n      background: rgba(11, 7, 7, 0.78);\\n    }\\n\\n    *::-webkit-scrollbar-thumb {\\n      background: rgba(244, 240, 234, 0.24);\\n      border: 2px solid rgba(11, 7, 7, 0.78);\\n      border-radius: 999px;\\n    }\\n\\n    a {\\n      color: inherit;\\n      text-decoration: none;\\n    }\\n\\n    .background-context {\\n      position: fixed;\\n      inset: 0;\\n      padding: 42px clamp(22px, 4.6vw, 72px);\\n      opacity: 0.1;\\n      filter: blur(1.5px);\\n      pointer-events: none;\\n    }\\n\\n    .ghost-header {\\n      height: 250px;\\n      border-bottom: 1px solid var(--line-soft);\\n    }\\n\\n    .ghost-name {\\n      margin: 0;\\n      font-family: var(--display);\\n      font-size: clamp(80px, 12vw, 150px);\\n      line-height: 0.76;\\n      text-transform: uppercase;\\n    }\\n\\n    .ghost-grid {\\n      display: grid;\\n      grid-template-columns: repeat(3, 1fr);\\n      gap: clamp(18px, 2vw, 30px);\\n      margin-top: 48px;\\n    }\\n\\n    .ghost-block {\\n      height: 340px;\\n      background: var(--panel);\\n      border: 1px solid var(--line-soft);\\n    }\\n\\n    .overlay-wrap {\\n      position: relative;\\n      z-index: 2;\\n      min-height: 100vh;\\n      display: grid;\\n      place-items: start center;\\n      padding: 16px 8px;\\n    }\\n\\n    .summary-panel {\\n      width: min(1180px, calc((100vw - 20px) / 1.10));\\n      max-height: none;\\n      overflow: visible;\\n      zoom: 1.10;\\n      padding: clamp(26px, 3.8vw, 48px);\\n      background: rgba(11, 7, 7, 0.965);\\n      border: 1px solid var(--line-soft);\\n      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.45);\\n    }\\n\\n    .panel-top {\\n      display: grid;\\n      grid-template-columns: 1fr auto;\\n      gap: 22px;\\n      align-items: start;\\n      margin-bottom: 14px;\\n    }\\n\\n    h1 {\\n      max-width: 720px;\\n      margin: 0;\\n      font-size: clamp(34px, 4.8vw, 56px);\\n      line-height: 0.9;\\n      font-weight: 400;\\n      letter-spacing: 0.055em;\\n      text-transform: uppercase;\\n    }\\n\\n    .pdf-link {\\n      justify-self: end;\\n      width: fit-content;\\n      padding-bottom: 4px;\\n      color: var(--muted);\\n      border-bottom: 1px solid var(--line);\\n      font-size: 11px;\\n      line-height: 1;\\n      letter-spacing: 0.08em;\\n      text-transform: uppercase;\\n      white-space: nowrap;\\n      transition: color 160ms ease, border-color 160ms ease;\\n    }\\n\\n    .pdf-link:hover {\\n      color: var(--accent-text);\\n      border-color: var(--accent-line);\\n    }\\n\\n    .project-type {\\n      margin: 0 0 14px;\\n      color: var(--muted);\\n      font-size: 10px;\\n      line-height: 1;\\n      font-weight: 500;\\n      letter-spacing: 0.1em;\\n      text-transform: uppercase;\\n    }\\n\\n    .summary-intro {\\n      max-width: 850px;\\n      margin: 0 0 28px;\\n      color: rgba(244, 240, 234, 0.76);\\n      font-size: 13px;\\n      line-height: 1.58;\\n      letter-spacing: 0.025em;\\n    }\\n\\n    .summary-grid,\\n    .design-grid {\\n      display: grid;\\n      gap: 18px;\\n    }\\n\\n    .summary-grid {\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      margin-bottom: 18px;\\n    }\\n\\n    .summary-card {\\n      padding: 18px;\\n      background: var(--panel-soft);\\n      border: 1px solid var(--line-soft);\\n    }\\n\\n    .summary-card.full {\\n      grid-column: 1 / -1;\\n    }\\n\\n    .summary-card h2 {\\n      margin: 0 0 14px;\\n      font-size: 12px;\\n      line-height: 1;\\n      font-weight: 500;\\n      letter-spacing: 0.12em;\\n      text-transform: uppercase;\\n    }\\n\\n    .section-heading {\\n      margin: 0 0 16px;\\n      color: rgba(244, 240, 234, 0.86);\\n      font-family: var(--display);\\n      font-size: 20px;\\n      line-height: 1;\\n      font-weight: 500;\\n      letter-spacing: 0.025em;\\n      text-transform: none;\\n    }\\n\\n    .summary-card > p {\\n      max-width: 850px;\\n      margin: 0;\\n      color: var(--muted);\\n      font-size: 12px;\\n      line-height: 1.55;\\n      letter-spacing: 0.035em;\\n    }\\n\\n    .visual-card,\\n    .evidence-card {\\n      display: grid;\\n      grid-template-rows: auto auto 1fr;\\n      gap: 11px;\\n      padding-top: 12px;\\n      border-top: 1px solid rgba(244, 240, 234, 0.10);\\n    }\\n\\n    .visual-card h3,\\n    .evidence-card h3 {\\n      margin: 0;\\n      font-size: 10px;\\n      line-height: 1;\\n      font-weight: 500;\\n      letter-spacing: 0.095em;\\n      text-transform: uppercase;\\n    }\\n\\n    .visual-card p,\\n    .evidence-card p {\\n      margin: 0;\\n      color: var(--muted);\\n      font-size: 11px;\\n      line-height: 1.42;\\n      letter-spacing: 0.035em;\\n    }\\n\\n    .media-frame {\\n      position: relative;\\n      width: 100%;\\n      display: grid;\\n      place-items: center;\\n      overflow: hidden;\\n      background: var(--panel);\\n      border: 1px solid var(--line-soft);\\n      box-shadow:\\n        inset 0 0 0 14px var(--panel),\\n        inset 0 0 0 15px var(--line-soft);\\n    }\\n\\n    .media-frame img,\\n    .media-frame video {\\n      display: block;\\n      width: 100%;\\n      height: 100%;\\n    }\\n\\n    .hero-card {\\n      margin-bottom: 24px;\\n    }\\n\\n    .hero-frame {\\n      aspect-ratio: 16 / 9;\\n      background: #000;\\n    }\\n\\n    .hero-frame video {\\n      object-fit: contain;\\n      object-position: center;\\n      background: #000;\\n    }\\n\\n    .system-list {\\n      display: grid;\\n      margin-top: 4px;\\n      border-top: 1px solid var(--line-soft);\\n    }\\n\\n    .system-row {\\n      display: grid;\\n      grid-template-columns: 0.29fr 1fr;\\n      gap: 18px;\\n      padding: 11px 0;\\n      border-bottom: 1px solid rgba(244, 240, 234, 0.10);\\n    }\\n\\n    .system-row strong,\\n    .system-row span {\\n      font-size: 11px;\\n      line-height: 1.48;\\n      letter-spacing: 0.04em;\\n    }\\n\\n    .system-row strong {\\n      color: var(--text);\\n      font-weight: 500;\\n      letter-spacing: 0.075em;\\n      text-transform: uppercase;\\n    }\\n\\n    .system-row span {\\n      color: var(--muted);\\n    }\\n\\n    .design-grid {\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      margin-top: 16px;\\n    }\\n\\n    .design-grid .media-frame {\\n      height: 340px;\\n    }\\n\\n    .swap-card,\\n    .swap-image {\\n      position: relative;\\n      width: 100%;\\n      height: 100%;\\n    }\\n\\n    .swap-card {\\n      outline: none;\\n    }\\n\\n    .swap-image img {\\n      position: absolute;\\n      inset: 0;\\n      transition: opacity 180ms ease;\\n    }\\n\\n    .default-image {\\n      opacity: 1;\\n    }\\n\\n    .hover-image {\\n      opacity: 0;\\n    }\\n\\n    .swap-card:hover .default-image,\\n    .swap-card:focus-visible .default-image {\\n      opacity: 0;\\n    }\\n\\n    .swap-card:hover .hover-image,\\n    .swap-card:focus-visible .hover-image {\\n      opacity: 1;\\n    }\\n\\n    .cad-image {\\n      object-fit: contain;\\n      object-position: center;\\n      padding: 18px;\\n      background: #ffffff;\\n      filter: saturate(0.78) contrast(1.02) brightness(0.99);\\n    }\\n\\n    .cad-frame {\\n      background: #ffffff;\\n      box-shadow:\\n        inset 0 0 0 14px #ffffff,\\n        inset 0 0 0 15px var(--line-soft);\\n    }\\n\\n    .cad-frame .swap-image {\\n      background: #ffffff;\\n    }\\n\\n    .hardware-grid .media-frame.cad-frame {\\n      height: 360px;\\n    }\\n\\n    .chamber-image {\\n      object-fit: cover;\\n      object-position: center;\\n      background: #000;\\n      filter: saturate(0.86) contrast(1.03) brightness(0.92);\\n    }\\n\\n    .validation-card {\\n      margin-top: 18px;\\n    }\\n\\n    .validation-frame {\\n      aspect-ratio: 5 / 3;\\n      background: #050505;\\n      box-shadow:\\n        inset 0 0 0 8px #050505,\\n        inset 0 0 0 9px var(--line-soft);\\n    }\\n\\n    .validation-frame img {\\n      object-fit: contain;\\n      object-position: center;\\n      padding: 6px;\\n      background: #050505;\\n    }\\n\\n    .cta-row {\\n      display: grid;\\n      grid-template-columns: 1fr auto 1fr;\\n      align-items: center;\\n      margin-top: 34px;\\n      padding-top: 22px;\\n      border-top: 1px solid var(--line-soft);\\n    }\\n\\n    .home-link {\\n      grid-column: 2;\\n      justify-self: center;\\n      min-width: 220px;\\n      padding: 10px 0;\\n      color: var(--text);\\n      text-align: center;\\n      border-top: 1px solid var(--accent-line);\\n      border-bottom: 1px solid var(--line-soft);\\n      font-size: 10px;\\n      line-height: 1;\\n      letter-spacing: 0.085em;\\n      text-transform: uppercase;\\n      transition: color 160ms ease, border-color 160ms ease;\\n    }\\n\\n    .home-link:hover {\\n      color: var(--accent-text);\\n      border-top-color: var(--accent-text);\\n      border-bottom-color: var(--accent-line);\\n    }\\n\\n    @media (max-width: 760px) {\\n      .background-context {\\n        opacity: 0.08;\\n        filter: blur(1px);\\n      }\\n\\n      .overlay-wrap {\\n        padding: 14px 10px;\\n      }\\n\\n      .summary-panel {\\n        width: 100%;\\n        max-width: 100%;\\n        max-height: none;\\n        overflow: visible;\\n        zoom: 1;\\n        padding: 22px 16px;\\n      }\\n\\n      h1 {\\n        font-size: 36px;\\n        line-height: 0.92;\\n      }\\n\\n      .summary-grid {\\n        grid-template-columns: 1fr;\\n        gap: 14px;\\n      }\\n\\n      .summary-card {\\n        padding: 16px;\\n      }\\n\\n      .system-row {\\n        grid-template-columns: 0.4fr 1fr;\\n        gap: 12px;\\n      }\\n\\n      .design-grid {\\n        gap: 12px;\\n      }\\n\\n      .design-grid .media-frame {\\n        height: 260px;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .design-grid {\\n        grid-template-columns: 1fr;\\n      }\\n\\n      .design-grid .media-frame {\\n        height: 300px;\\n      }\\n\\n      .validation-frame {\\n        aspect-ratio: 4 / 3;\\n      }\\n    }\\n\\n    @media (max-width: 520px) {\\n      .panel-top {\\n        grid-template-columns: 1fr;\\n      }\\n\\n      .pdf-link {\\n        justify-self: start;\\n      }\\n\\n      .system-row {\\n        grid-template-columns: 1fr;\\n        gap: 3px;\\n      }\\n\\n      .cta-row {\\n        grid-template-columns: 1fr;\\n      }\\n\\n      .home-link {\\n        grid-column: 1;\\n        justify-self: start;\\n        min-width: 180px;\\n      }\\n    }\\n  \\n    /* Shared portfolio project footer */\\n    .project-footer {\\n      display: grid;\\n      grid-template-columns: 1fr auto;\\n      gap: 24px;\\n      align-items: start;\\n      margin-top: 38px;\\n      padding-top: 22px;\\n      border-top: 1px solid var(--line-soft);\\n    }\\n\\n    .all-projects-link {\\n      display: inline-flex;\\n      align-items: center;\\n      gap: 8px;\\n      width: fit-content;\\n      color: rgba(244, 240, 234, 0.48);\\n      font-size: 9px;\\n      line-height: 1;\\n      letter-spacing: 0.09em;\\n      text-transform: uppercase;\\n      transition: color 160ms ease;\\n    }\\n\\n    .all-projects-link:hover {\\n      color: var(--text);\\n    }\\n\\n    .next-project-link {\\n      display: grid;\\n      justify-items: end;\\n      gap: 7px;\\n      text-align: right;\\n    }\\n\\n    .next-project-label {\\n      color: rgba(244, 240, 234, 0.42);\\n      font-size: 9px;\\n      line-height: 1;\\n      letter-spacing: 0.10em;\\n      text-transform: uppercase;\\n    }\\n\\n    .next-project-title {\\n      color: var(--text);\\n      font-family: var(--sans);\\n      font-size: 13px;\\n      line-height: 1.25;\\n      font-weight: 500;\\n      letter-spacing: 0.08em;\\n      text-transform: uppercase;\\n      transition: color 160ms ease;\\n    }\\n\\n    .next-project-link:hover .next-project-title {\\n      color: var(--accent-text);\\n    }\\n\\n    @media (max-width: 520px) {\\n      .project-footer {\\n        grid-template-columns: 1fr auto;\\n        gap: 14px;\\n      }\\n\\n      .next-project-title {\\n        font-size: 12px;\\n      }\\n    }\\n\\n\\n    /* Upper-limb sensing visual hierarchy */\\n    .hero-frame img,\\n    .hero-frame video {\\n      width: 100%;\\n      height: 100%;\\n      object-fit: contain;\\n      object-position: center;\\n      background: #000;\\n    }\\n\\n    .component-row,\\n    .system-cad-row,\\n    .hardware-grid,\\n    .result-grid {\\n      display: grid;\\n      gap: 18px;\\n      margin-top: 16px;\\n      align-items: start;\\n    }\\n\\n    .component-row {\\n      grid-template-columns: repeat(3, minmax(0, 1fr));\\n      max-width: 760px;\\n      margin-left: auto;\\n      margin-right: auto;\\n    }\\n\\n    .system-cad-row,\\n    .hardware-grid,\\n    .result-grid {\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n    }\\n\\n    .component-row .media-frame {\\n      height: 145px;\\n      background: #ffffff;\\n    }\\n\\n    .system-cad-row .media-frame {\\n      height: 180px;\\n      background: #ffffff;\\n    }\\n\\n    .hardware-grid .media-frame,\\n    .result-grid .media-frame {\\n      height: 300px;\\n    }\\n\\n    .component-photo,\\n    .cad-image {\\n      object-fit: contain;\\n      object-position: center;\\n      padding: 14px;\\n      background: #ffffff;\\n      filter: saturate(0.92) contrast(1.01) brightness(0.99);\\n    }\\n\\n    .wearing-photo {\\n      object-fit: cover;\\n      object-position: center;\\n      background: #000;\\n      filter: saturate(0.88) contrast(1.03) brightness(0.93);\\n    }\\n\\n    .electronics-photo {\\n      object-fit: contain;\\n      object-position: center;\\n      padding: 12px;\\n      background: #ffffff;\\n      filter: saturate(0.9) contrast(1.02) brightness(0.98);\\n    }\\n\\n    .dashboard-image {\\n      object-fit: contain;\\n      object-position: center;\\n      padding: 6px;\\n      background: #050505;\\n    }\\n\\n    .integrated-test-photo {\\n      object-fit: cover;\\n      object-position: center;\\n      background: #050505;\\n      filter: saturate(0.9) contrast(1.02) brightness(0.95);\\n    }\\n\\n    .pdf-video-poster {\\n      display: none !important;\\n    }\\n\\n    .visual-card.header-only {\\n      grid-template-rows: auto auto;\\n    }\\n\\n    .hardware-separator-copy {\\n      margin-top: 26px !important;\\n      margin-bottom: 4px !important;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .component-row,\\n      .system-cad-row,\\n      .hardware-grid,\\n      .result-grid {\\n        gap: 12px;\\n      }\\n\\n      .component-row .media-frame {\\n        height: 125px;\\n      }\\n\\n      .system-cad-row .media-frame {\\n        height: 160px;\\n      }\\n\\n      .hardware-grid .media-frame,\\n      .result-grid .media-frame {\\n        height: 250px;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .system-cad-row,\\n      .hardware-grid,\\n      .result-grid {\\n        grid-template-columns: 1fr;\\n      }\\n\\n      .component-row {\\n        grid-template-columns: repeat(3, minmax(0, 1fr));\\n        gap: 8px;\\n      }\\n\\n      .component-row .media-frame {\\n        height: 105px;\\n      }\\n\\n      .system-cad-row .media-frame {\\n        height: 180px;\\n      }\\n\\n      .hardware-grid .media-frame,\\n      .result-grid .media-frame {\\n        height: 300px;\\n      }\\n    }\\n  \\n\\n\\n    /* Media sizing: preserve each source image's natural orientation. */\\n    .top-showcase {\\n      grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.7fr);\\n      align-items: stretch;\\n      max-width: 850px;\\n      margin-left: auto;\\n      margin-right: auto;\\n    }\\n\\n    .top-showcase .visual-card {\\n      min-width: 0;\\n    }\\n\\n    .top-showcase .media-frame {\\n      height: 350px;\\n      padding: 0;\\n      background: #050505;\\n      box-shadow: none;\\n    }\\n\\n    .top-showcase .wearing-photo {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: cover;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    .top-showcase .dashboard-image {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: contain;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    /* CAD/component views may contain their own white canvas; do not add a second border of padding. */\\n    .component-row .media-frame {\\n      padding: 0;\\n      background: #ffffff;\\n      box-shadow: none;\\n    }\\n\\n    .component-row .component-photo,\\n    .component-row .cad-image {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: contain;\\n      object-position: center;\\n      background: #ffffff;\\n    }\\n\\n    /* Electronics is the primary hardware view; sleeve is a narrow supporting crop. */\\n    .hardware-grid {\\n      grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);\\n      max-width: 820px;\\n      margin-left: auto;\\n      margin-right: auto;\\n      align-items: stretch;\\n    }\\n\\n    .hardware-grid .media-frame {\\n      width: 100%;\\n      height: 330px;\\n      padding: 0;\\n      background: #050505;\\n      box-shadow: none;\\n    }\\n\\n    .hardware-grid .electronics-photo {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: cover;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    .hardware-grid .sleeve-photo {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: cover;\\n      object-position: 50% 50%;\\n      background: #050505;\\n    }\\n\\n    /* Final test evidence: equal image/video split. */\\n    .final-test-grid {\\n      display: grid;\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      gap: 18px;\\n      margin-top: 18px;\\n      align-items: start;\\n    }\\n\\n    .final-test-grid .media-frame {\\n      width: 100%;\\n      aspect-ratio: 16 / 10;\\n      height: auto;\\n      padding: 0;\\n      background: #050505;\\n      box-shadow: none;\\n    }\\n\\n    .final-test-grid img,\\n    .final-test-grid video {\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    /* Integrated test photo is 2048x1439; match that ratio instead of forcing 5:3. */\\n    .validation-frame {\\n      aspect-ratio: 2048 / 1439;\\n      padding: 0;\\n      box-shadow: none;\\n    }\\n\\n    .validation-frame .integrated-test-photo {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: cover;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    /* The final demo is 1790x1080; matching it removes arbitrary black bars. */\\n    .demo-video-card .hero-frame {\\n      aspect-ratio: 1790 / 1080;\\n      height: auto;\\n      padding: 0;\\n      box-shadow: none;\\n    }\\n\\n    .demo-video-card .hero-frame video {\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover;\\n      object-position: center;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .top-showcase {\\n        grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.7fr);\\n      }\\n\\n      .top-showcase .media-frame {\\n        height: 280px;\\n      }\\n\\n      .hardware-grid {\\n        max-width: 720px;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .top-showcase {\\n        grid-template-columns: 1fr;\\n      }\\n\\n      .top-showcase .media-frame {\\n        height: auto;\\n      }\\n\\n      .top-showcase .visual-card:first-child .media-frame {\\n        aspect-ratio: 1479 / 2048;\\n      }\\n\\n      .top-showcase .visual-card:last-child .media-frame {\\n        aspect-ratio: 16 / 9;\\n      }\\n\\n      .hardware-grid,\\n      .final-test-grid {\\n        grid-template-columns: 1fr;\\n        max-width: 430px;\\n      }\\n\\n      .hardware-grid .media-frame {\\n        height: 300px;\\n      }\\n    }\\n\\n\\n    /* Clean, aligned split layouts. */\\n    .top-showcase {\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      max-width: 900px;\\n      gap: 18px;\\n      align-items: stretch;\\n    }\\n\\n    .top-showcase .visual-card,\\n    .final-test-grid .visual-card,\\n    .hardware-grid .visual-card {\\n      min-width: 0;\\n      align-self: stretch;\\n    }\\n\\n    .top-showcase .media-frame {\\n      height: 320px;\\n    }\\n\\n    .top-showcase .wearing-photo {\\n      object-fit: cover;\\n      object-position: 50% 48%;\\n    }\\n\\n    .top-showcase .dashboard-image {\\n      object-fit: contain;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    .hardware-grid {\\n      grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);\\n      max-width: 860px;\\n      gap: 18px;\\n      align-items: stretch;\\n    }\\n\\n    .hardware-grid .media-frame {\\n      height: 340px;\\n    }\\n\\n    .hardware-grid .electronics-photo {\\n      object-fit: cover;\\n      object-position: center;\\n    }\\n\\n    .hardware-grid .sleeve-photo {\\n      object-fit: cover;\\n      object-position: 50% 50%;\\n    }\\n\\n    .final-test-grid {\\n      grid-template-columns: repeat(2, minmax(0, 1fr));\\n      gap: 18px;\\n      align-items: stretch;\\n    }\\n\\n    .final-test-grid .visual-card {\\n      grid-template-rows: 300px auto;\\n      gap: 11px;\\n    }\\n\\n    .final-test-grid .media-frame {\\n      width: 100%;\\n      height: 300px;\\n      aspect-ratio: auto;\\n      padding: 0;\\n    }\\n\\n    .final-test-grid img,\\n    .final-test-grid video {\\n      display: block;\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover;\\n      object-position: center;\\n      margin: 0;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .top-showcase .media-frame {\\n        height: 280px;\\n      }\\n\\n      .final-test-grid .visual-card {\\n        grid-template-rows: 260px auto;\\n      }\\n\\n      .final-test-grid .media-frame {\\n        height: 260px;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .top-showcase,\\n      .hardware-grid,\\n      .final-test-grid {\\n        grid-template-columns: 1fr;\\n        max-width: 430px;\\n      }\\n\\n      .top-showcase .media-frame,\\n      .hardware-grid .media-frame,\\n      .final-test-grid .media-frame {\\n        height: 300px;\\n      }\\n\\n      .final-test-grid .visual-card {\\n        grid-template-rows: 300px auto;\\n      }\\n    }\\n\\n    /* Final media layout: natural aspect ratios, no forced 50/50 cropping. */\\n    .top-showcase {\\n      grid-template-columns: minmax(0, 0.722fr) minmax(0, 1.778fr);\\n      max-width: 900px;\\n      gap: 18px;\\n      align-items: start;\\n      margin-left: auto;\\n      margin-right: auto;\\n    }\\n\\n    .top-showcase .visual-card {\\n      min-width: 0;\\n    }\\n\\n    .top-showcase .media-frame {\\n      width: 100%;\\n      height: auto;\\n      padding: 0;\\n      overflow: hidden;\\n      background: #050505;\\n      box-shadow: none;\\n    }\\n\\n    .top-showcase .visual-card:first-child .media-frame {\\n      aspect-ratio: 1479 / 2048;\\n    }\\n\\n    .top-showcase .visual-card:last-child .media-frame {\\n      aspect-ratio: 16 / 9;\\n    }\\n\\n    .top-showcase .wearing-photo,\\n    .top-showcase .dashboard-image {\\n      display: block;\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: contain;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    .final-test-grid.video-only {\\n      display: block;\\n      width: 100%;\\n      max-width: 900px;\\n      margin: 18px auto 0;\\n    }\\n\\n    .final-test-grid.video-only .visual-card {\\n      display: grid;\\n      grid-template-rows: auto auto;\\n      gap: 11px;\\n      width: 100%;\\n    }\\n\\n    .final-test-grid.video-only .media-frame {\\n      width: 100%;\\n      height: auto;\\n      aspect-ratio: 1790 / 1080;\\n      padding: 0;\\n      overflow: hidden;\\n      background: #050505;\\n      box-shadow: none;\\n    }\\n\\n    .final-test-grid.video-only video {\\n      display: block;\\n      width: 100%;\\n      height: 100%;\\n      margin: 0;\\n      object-fit: contain;\\n      object-position: center;\\n      background: #050505;\\n    }\\n\\n    @media (max-width: 600px) {\\n      .top-showcase {\\n        grid-template-columns: 1fr;\\n        max-width: 430px;\\n      }\\n\\n      .top-showcase .visual-card:first-child .media-frame {\\n        aspect-ratio: 1479 / 2048;\\n      }\\n\\n      .top-showcase .visual-card:last-child .media-frame {\\n        aspect-ratio: 16 / 9;\\n      }\\n\\n      .final-test-grid.video-only {\\n        max-width: 430px;\\n      }\\n    }\\n\\n    @media print {\\n      @page {\\n        size: Letter portrait;\\n        margin: 0;\\n      }\\n\\n      html,\\n      body {\\n        width: 100%;\\n        min-height: 0;\\n        overflow: visible !important;\\n        background: #0b0707 !important;\\n        -webkit-print-color-adjust: exact !important;\\n        print-color-adjust: exact !important;\\n      }\\n\\n      .background-context {\\n        display: none !important;\\n      }\\n\\n      .overlay-wrap {\\n        display: block !important;\\n        min-height: 0 !important;\\n        padding: 0 !important;\\n      }\\n\\n      .summary-panel {\\n        width: 100% !important;\\n        max-width: none !important;\\n        max-height: none !important;\\n        overflow: visible !important;\\n        padding: 0.42in !important;\\n        border: 0 !important;\\n        box-shadow: none !important;\\n        background: #0b0707 !important;\\n      }\\n\\n      .pdf-link,\\n      .project-footer {\\n        display: none !important;\\n      }\\n\\n      .media-frame video {\\n        display: none !important;\\n      }\\n\\n      .media-frame .pdf-video-poster {\\n        display: block !important;\\n        width: 100% !important;\\n        height: 100% !important;\\n        object-fit: cover !important;\\n        object-position: center !important;\\n      }\\n\\n      .hero-card,\\n      .summary-card,\\n      .visual-card,\\n      .system-row,\\n      .component-row,\\n      .hardware-grid,\\n      .result-grid {\\n        break-inside: avoid;\\n        page-break-inside: avoid;\\n      }\\n\\n      .summary-grid {\\n        display: block !important;\\n      }\\n\\n      .summary-card {\\n        margin-bottom: 18px;\\n      }\\n\\n      .summary-intro {\\n        margin-bottom: 18px;\\n      }\\n\\n      .hero-frame {\\n        max-height: 4.1in;\\n      }\\n\\n      .component-row .media-frame {\\n        height: 1.55in !important;\\n      }\\n\\n      .hardware-grid .media-frame,\\n      .result-grid .media-frame {\\n        height: 2.45in !important;\\n      }\\n    }\\n\\n\\n    .demo-video-card {\\n      width: min(690px, 100%);\\n      margin: 28px auto 0;\\n    }\\n\\n\\n    /* Electronics split crop fix: preserve full open-pod photo in the 2/3 column. */\\n    .hardware-grid .media-frame {\\n      height: 560px;\\n    }\\n\\n    .hardware-grid .electronics-card .media-frame {\\n      background: #c9c8c2;\\n    }\\n\\n    .hardware-grid .electronics-photo {\\n      width: 100%;\\n      height: 100%;\\n      padding: 0;\\n      object-fit: contain !important;\\n      object-position: center !important;\\n      background: #c9c8c2;\\n    }\\n\\n    .hardware-grid .sleeve-photo {\\n      width: 100%;\\n      height: 100%;\\n      object-fit: cover !important;\\n      object-position: 50% 50% !important;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .hardware-grid .media-frame {\\n        height: 480px;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .hardware-grid .media-frame {\\n        height: auto;\\n      }\\n\\n      .hardware-grid .electronics-card .media-frame {\\n        aspect-ratio: 3 / 4;\\n      }\\n\\n      .hardware-grid .visual-card:not(.electronics-card) .media-frame {\\n        aspect-ratio: 4 / 5;\\n      }\\n    }\\n\\n  \\n    /* Final size reduction: keep these media sections compact on desktop and stacked/mobile views. */\\n    .hardware-grid {\\n      max-width: 700px !important;\\n      margin-left: auto !important;\\n      margin-right: auto !important;\\n    }\\n\\n    .hardware-grid .media-frame {\\n      height: 390px !important;\\n    }\\n\\n    .final-test-grid.video-only {\\n      max-width: 560px !important;\\n      margin-left: auto !important;\\n      margin-right: auto !important;\\n    }\\n\\n    .demo-video-card {\\n      width: 100% !important;\\n      max-width: 560px !important;\\n      margin-left: auto !important;\\n      margin-right: auto !important;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .hardware-grid {\\n        max-width: 600px !important;\\n      }\\n\\n      .hardware-grid .media-frame {\\n        height: 340px !important;\\n      }\\n\\n      .final-test-grid.video-only,\\n      .demo-video-card {\\n        max-width: 500px !important;\\n      }\\n    }\\n\\n    @media (max-width: 600px) {\\n      .hardware-grid {\\n        max-width: 320px !important;\\n        grid-template-columns: 1fr !important;\\n      }\\n\\n      .hardware-grid .media-frame,\\n      .hardware-grid .electronics-card .media-frame,\\n      .hardware-grid .visual-card:not(.electronics-card) .media-frame {\\n        height: 290px !important;\\n        aspect-ratio: auto !important;\\n      }\\n\\n      .final-test-grid.video-only,\\n      .demo-video-card {\\n        max-width: 360px !important;\\n      }\\n    }\\n\\n  \\n\\n    /* Approved finishing accents only \\u2014 preserves the original corrected project-page design. */\\n    :host {\\n      --portfolio-orange: #FF7A32;\\n      --portfolio-orange-hover: #FF9B65;\\n      --portfolio-orange-line: rgba(255,122,50,.72);\\n    }\\n    .pdf-link, .pdf-link:visited {\\n      color: var(--portfolio-orange) !important;\\n      border-bottom-color: var(--portfolio-orange-line) !important;\\n    }\\n    .pdf-link:hover, .pdf-link:focus-visible {\\n      color: var(--portfolio-orange-hover) !important;\\n      border-bottom-color: var(--portfolio-orange-hover) !important;\\n    }\\n    a:hover, button:hover {\\n      --accent-text: var(--portfolio-orange);\\n    }\\n    .swap-card:hover .media-frame,\\n    .swap-card:focus-visible .media-frame {\\n      border-color: var(--portfolio-orange-line) !important;\\n    }\\n    .next-project-link:hover .next-project-title,\\n    .next-project-link:focus-visible .next-project-title,\\n    .archive-link:hover, .archive-link:focus-visible {\\n      color: var(--portfolio-orange) !important;\\n    }\\n    :focus-visible { outline-color: var(--portfolio-orange) !important; }\\n  \\n\\n    /* Project-page visual match to the approved homepage. Layout/content intentionally untouched. */\\n    :host {\\n      --project-bg: #000102;\\n      --project-bg-deep: #000000;\\n      --project-panel: #010407;\\n      --project-panel-soft: rgba(5, 14, 21, 0.54);\\n      --project-text: #edf0f2;\\n      --project-muted: #87939a;\\n      --project-blue: #405b68;\\n      --project-blue-hover: #6a828d;\\n      --project-line: rgba(54, 75, 86, 0.18);\\n      --project-line-soft: rgba(54, 75, 86, 0.095);\\n      --project-orange: #FF7A32;\\n      --project-orange-hover: #FF9B65;\\n      --project-orange-soft: rgba(255, 122, 50, 0.14);\\n      --project-orange-line: rgba(255, 122, 50, 0.76);\\n    }\\n\\n    html {\\n      background: var(--project-bg) !important;\\n      color-scheme: dark;\\n    }\\n\\n    body {\\n      color: var(--project-text) !important;\\n      background:\\n        radial-gradient(850px 520px at 88% 0%, rgba(8, 17, 23, 0.055), transparent 78%),\\n        radial-gradient(760px 560px at 4% 58%, rgba(8, 20, 28, 0.035), transparent 80%),\\n        linear-gradient(180deg, var(--project-bg) 0%, #010305 50%, var(--project-bg-deep) 100%) !important;\\n      -webkit-font-smoothing: antialiased;\\n      -moz-osx-font-smoothing: grayscale;\\n      scrollbar-color: rgba(106, 130, 141, 0.36) rgba(0, 1, 2, 0.92) !important;\\n    }\\n\\n    *::-webkit-scrollbar-track {\\n      background: rgba(0, 1, 2, 0.92) !important;\\n    }\\n\\n    *::-webkit-scrollbar-thumb {\\n      background: rgba(106, 130, 141, 0.30) !important;\\n      border-color: rgba(0, 1, 2, 0.92) !important;\\n    }\\n\\n    *::-webkit-scrollbar-thumb:hover {\\n      background: rgba(106, 130, 141, 0.48) !important;\\n    }\\n\\n    ::selection {\\n      color: var(--project-text);\\n      background: rgba(255, 122, 50, 0.28);\\n    }\\n\\n    /* Keep the original background composition but shift it into the homepage palette. */\\n    .background-context {\\n      opacity: 0.13 !important;\\n      filter: blur(1.35px) !important;\\n    }\\n\\n    .ghost-header {\\n      border-bottom-color: var(--project-line-soft) !important;\\n    }\\n\\n    .ghost-name {\\n      color: rgba(106, 130, 141, 0.34) !important;\\n    }\\n\\n    .ghost-block {\\n      background: rgba(3, 8, 12, 0.82) !important;\\n      border-color: var(--project-line-soft) !important;\\n    }\\n\\n    /* Same blue-black depth as the homepage rather than the old brown/black panel. */\\n    .summary-panel {\\n      background:\\n        radial-gradient(700px 320px at 8% 0%, rgba(20, 43, 56, 0.10), transparent 72%),\\n        linear-gradient(180deg, rgba(3, 8, 12, 0.985), rgba(1, 4, 7, 0.985)) !important;\\n      border-color: var(--project-line) !important;\\n      box-shadow:\\n        0 28px 80px rgba(0, 0, 0, 0.48),\\n        0 0 0 1px rgba(64, 91, 104, 0.025) !important;\\n    }\\n\\n    h1 {\\n      color: var(--project-text) !important;\\n      text-wrap: balance;\\n    }\\n\\n    /* Small permanent orange cue: present on every project, including pages without PDFs. */\\n    h1::after {\\n      content: '';\\n      display: block;\\n      width: 34px;\\n      height: 2px;\\n      margin-top: 17px;\\n      background: var(--project-orange);\\n      box-shadow: 0 0 12px rgba(255, 122, 50, 0.10);\\n    }\\n\\n    .summary-intro,\\n    .summary-card p,\\n    .visual-card p,\\n    .system-row span,\\n    .next-project-label,\\n    .all-projects-link,\\n    .project-files-link,\\n    .home-link {\\n      color: var(--project-muted) !important;\\n    }\\n\\n    .summary-card {\\n      background:\\n        linear-gradient(180deg, rgba(5, 14, 21, 0.58), rgba(2, 7, 11, 0.52)) !important;\\n      border-color: var(--project-line-soft) !important;\\n    }\\n\\n    .summary-card h2,\\n    .section-heading {\\n      color: var(--project-blue-hover) !important;\\n    }\\n\\n    .visual-card {\\n      border-top-color: var(--project-line-soft) !important;\\n    }\\n\\n    .visual-card h3,\\n    .system-row strong {\\n      color: #c9d2d6 !important;\\n    }\\n\\n    .system-list,\\n    .project-footer,\\n    .cta-row {\\n      border-color: var(--project-line-soft) !important;\\n    }\\n\\n    .system-row {\\n      border-bottom-color: var(--project-line-soft) !important;\\n    }\\n\\n    /* Image framing follows the homepage: cool neutral border at rest, orange only when interactive. */\\n    .media-frame {\\n      background: var(--project-bg) !important;\\n      border-color: var(--project-line-soft) !important;\\n      box-shadow:\\n        inset 0 0 0 14px var(--project-panel),\\n        inset 0 0 0 15px var(--project-line-soft) !important;\\n    }\\n\\n    .media-frame.cad {\\n      /* Preserve the existing light CAD plate while harmonizing its outer edge. */\\n      border-color: rgba(64, 91, 104, 0.24) !important;\\n    }\\n\\n    .swap-card .media-frame {\\n      transition: border-color 180ms ease, box-shadow 200ms ease, transform 200ms ease !important;\\n    }\\n\\n    .swap-card:hover .media-frame,\\n    .swap-card:focus-visible .media-frame {\\n      border-color: var(--project-orange-line) !important;\\n      box-shadow:\\n        0 0 0 1px rgba(255, 122, 50, 0.18),\\n        0 0 22px var(--project-orange-soft) !important;\\n      transform: translateY(-1px);\\n    }\\n\\n    .swap-card:hover .media-frame.cad,\\n    .swap-card:focus-visible .media-frame.cad {\\n      box-shadow:\\n        inset 0 0 0 10px var(--cad-bg),\\n        inset 0 0 0 11px var(--project-orange-line),\\n        0 0 22px var(--project-orange-soft) !important;\\n    }\\n\\n    /* Blue is the structural accent. Orange means action. */\\n    .pdf-link,\\n    .pdf-link:visited {\\n      color: var(--project-orange) !important;\\n      border-bottom-color: var(--project-orange-line) !important;\\n    }\\n\\n    .pdf-link:hover,\\n    .pdf-link:focus-visible {\\n      color: var(--project-orange-hover) !important;\\n      border-bottom-color: var(--project-orange-hover) !important;\\n    }\\n\\n    .archive-link {\\n      border-top-color: var(--project-blue) !important;\\n      border-bottom-color: var(--project-line-soft) !important;\\n    }\\n\\n    .home-link:hover,\\n    .home-link:focus-visible,\\n    .archive-link:hover,\\n    .archive-link:focus-visible,\\n    .all-projects-link:hover,\\n    .all-projects-link:focus-visible,\\n    .project-files-link:hover,\\n    .project-files-link:focus-visible,\\n    .next-project-link:hover .next-project-title,\\n    .next-project-link:focus-visible .next-project-title {\\n      color: var(--project-orange) !important;\\n      border-color: var(--project-orange-line) !important;\\n    }\\n\\n    .next-project-title {\\n      color: var(--project-text) !important;\\n    }\\n\\n    :focus-visible {\\n      outline-color: var(--project-orange) !important;\\n    }\\n\\n    @media (max-width: 760px) {\\n      .background-context { opacity: 0.09 !important; }\\n      h1::after { margin-top: 14px; }\\n    }\\n  \\n\\n  /* Final project-page colour match. Layout/content intentionally untouched. */\\n  :host {\\n    --project-bg: #010305;\\n    --project-bg-mid: #020507;\\n    --project-bg-deep: #000102;\\n    --project-panel: #03070a;\\n    --project-title-blue: #49636f;\\n    --project-heading-blue: #6a828d;\\n    --project-subheading: #bcc5ca;\\n    --project-body-grey: #849198;\\n    --project-muted-grey: #747d83;\\n  }\\n\\n  html { background: var(--project-bg) !important; }\\n\\n  body {\\n    background:\\n      radial-gradient(900px 620px at 90% 0%, rgba(13, 25, 33, 0.038), transparent 76%),\\n      radial-gradient(760px 540px at 4% 58%, rgba(7, 15, 21, 0.017), transparent 82%),\\n      linear-gradient(180deg, var(--project-bg) 0%, var(--project-bg-mid) 52%, var(--project-bg-deep) 100%) !important;\\n  }\\n\\n  .summary-panel {\\n    background:\\n      radial-gradient(700px 320px at 8% 0%, rgba(20, 43, 56, 0.08), transparent 72%),\\n      linear-gradient(180deg, rgba(3, 7, 10, 0.985), rgba(1, 4, 7, 0.985)) !important;\\n  }\\n\\n  /* Home-page hierarchy: blue titles, grey prose, orange interaction. */\\n  h1 {\\n    color: var(--project-title-blue) !important;\\n  }\\n\\n  .summary-card h2,\\n  .section-heading {\\n    color: var(--project-heading-blue) !important;\\n  }\\n\\n  .visual-card h3,\\n  .system-row strong,\\n  .next-project-title {\\n    color: var(--project-subheading) !important;\\n  }\\n\\n  .summary-intro,\\n  .summary-card p,\\n  .visual-card p,\\n  .system-row span,\\n  .next-project-label,\\n  .all-projects-link,\\n  .project-files-link,\\n  .home-link,\\n  .archive-link,\\n  .image-caption,\\n  figcaption,\\n  .caption,\\n  li {\\n    color: var(--project-body-grey) !important;\\n  }\\n\\n  .image-label,\\n  .meta,\\n  .eyebrow,\\n  .kicker {\\n    color: var(--project-muted-grey) !important;\\n  }\\n\\n  /* Preserve the established orange action language. */\\n  .pdf-link,\\n  .pdf-link:visited {\\n    color: var(--project-orange) !important;\\n    border-bottom-color: var(--project-orange-line) !important;\\n  }\\n\\n  .pdf-link:hover,\\n  .pdf-link:focus-visible,\\n  a:hover,\\n  a:focus-visible {\\n    text-decoration-color: var(--project-orange) !important;\\n  }\\n\\n\\n/* Intro/story layer is intentionally contained inside the original project panel. */\\n.project-story-intro{\\n  position:relative;\\n  display:grid;\\n  grid-template-columns:minmax(0,1.05fr) minmax(280px,.95fr);\\n  gap:clamp(30px,4.5vw,58px);\\n  align-items:center;\\n  width:100%;\\n  margin:0 0 clamp(38px,5vw,56px);\\n  padding:clamp(8px,1vw,12px) 0 clamp(38px,5vw,52px);\\n  border-bottom:1px solid var(--project-line-soft,rgba(64,91,104,.14));\\n  overflow:visible;\\n}\\n.project-story-copy{min-width:0;max-width:620px}\\n.project-story-kicker{margin:0 0 14px;color:var(--project-orange,#FF7A32)!important;font:500 9px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase}\\n.project-story-title{margin:0;color:var(--project-title-blue,#49636f)!important;font-family:var(--sans);font-size:clamp(36px,4.8vw,60px);line-height:.94;font-weight:400;letter-spacing:.025em;text-transform:uppercase;text-wrap:balance}\\n.project-story-subtitle{margin:13px 0 0;color:var(--project-heading-blue,#6a828d)!important;font:500 10px/1.4 var(--sans);letter-spacing:.09em;text-transform:uppercase}\\n.project-story-statement{margin:clamp(22px,3vw,30px) 0 0;max-width:58ch;color:#a8b3b8!important;font-family:var(--display,Georgia,serif);font-size:clamp(17px,1.65vw,22px);line-height:1.4;letter-spacing:.005em}\\n\\n.project-story-actions{display:flex;flex-wrap:wrap;gap:10px 22px;align-items:center;margin-top:26px}\\n.project-story-action{display:inline-flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid transparent;color:var(--project-body-grey,#849198)!important;font:500 9px/1 var(--sans);letter-spacing:.09em;text-transform:uppercase;transition:color 180ms ease,border-color 180ms ease,transform 280ms cubic-bezier(.22,1,.36,1)}\\n.project-story-action.primary{color:var(--project-orange,#FF7A32)!important;border-bottom-color:rgba(255,122,50,.42)}\\n.project-story-action:hover,.project-story-action:focus-visible{color:var(--project-orange-hover,#ff9a63)!important;border-bottom-color:var(--project-orange,#FF7A32);transform:translateY(-1px);outline:none}\\n.project-story-visual{min-width:0;margin:0}\\n.project-story-frame{position:relative;width:100%;aspect-ratio:4/3;overflow:hidden;background:var(--project-panel,#03070a);border:1px solid rgba(74,101,114,.22);box-shadow:0 20px 48px rgba(0,0,0,.23)}\\n.project-story-frame::before{content:'';position:absolute;z-index:2;left:0;top:0;width:38px;height:38px;border-left:1px solid rgba(255,122,50,.62);border-top:1px solid rgba(255,122,50,.62);pointer-events:none}\\n.project-story-frame img{display:block;width:100%;height:100%;object-fit:var(--story-fit,cover);object-position:var(--story-position,center);background:var(--story-bg,transparent);filter:saturate(.94) brightness(.94) contrast(1.02);transform:scale(var(--story-scale,1))}\\n.project-story-caption{margin:9px 0 0;color:var(--project-muted-grey,#747d83)!important;font:500 8px/1.4 var(--sans);letter-spacing:.08em;text-transform:uppercase}\\n.technical-depth-cue{display:flex;align-items:center;gap:11px;margin:0 0 22px;color:var(--project-muted-grey,#747d83)!important;font:500 9px/1 var(--sans);letter-spacing:.11em;text-transform:uppercase;scroll-margin-top:28px}\\n.technical-depth-cue::before{content:'';width:25px;height:1px;background:var(--project-orange,#FF7A32)}\\n\\n/* Natural motion: one directional entrance. No blur, no transform feedback loop. */\\n.story-motion .project-story-copy,.story-motion .project-story-visual,.story-motion .story-flow-target{\\n  opacity:.001;\\n  transform:translate3d(var(--story-enter-x,0),var(--story-enter-y,14px),0);\\n  transition:transform 900ms cubic-bezier(.22,1,.36,1),opacity 620ms ease-out;\\n}\\n.story-motion .project-story-copy{--story-enter-x:-42px;--story-enter-y:0}\\n.story-motion .project-story-visual{--story-enter-x:42px;--story-enter-y:0;transition-delay:90ms}\\n.story-motion .story-flow-target:nth-of-type(even){--story-enter-x:28px}\\n.story-motion .story-flow-target:nth-of-type(odd){--story-enter-x:-28px}\\n.story-motion .story-in-view{opacity:1;transform:translate3d(0,0,0)}\\n/* Only the large heading drifts out as the story chapter leaves. Paragraphs remain readable/fitted. */\\n.project-story-title{translate:var(--story-title-drift,0px) 0;will-change:translate}\\n.project-story-kicker{translate:var(--story-kicker-drift,0px) 0;will-change:translate}\\n\\n@media(max-width:820px){\\n .project-story-intro{grid-template-columns:1fr;gap:28px;padding-bottom:38px}\\n .project-story-copy{max-width:none}.project-story-visual{width:min(100%,640px)}\\n .project-story-frame{aspect-ratio:16/8;max-height:240px}\\n .project-story-statement{max-width:68ch;font-size:17px;line-height:1.36;margin-top:18px}\\n \\n}\\n@media(max-width:560px){\\n .project-story-title{font-size:clamp(34px,11vw,48px)}\\n .project-story-actions{align-items:flex-start;flex-direction:column;gap:5px}\\n .project-story-visual{width:100%}.project-story-frame{max-height:200px}\\n \\n .story-motion .project-story-copy,.story-motion .project-story-visual,.story-motion .story-flow-target{opacity:1;transform:none;transition:none}\\n .project-story-title,.project-story-kicker{translate:none!important}\\n}\\n@media(prefers-reduced-motion:reduce){\\n .story-motion .project-story-copy,.story-motion .project-story-visual,.story-motion .story-flow-target{opacity:1!important;transform:none!important;transition:none!important}\\n .project-story-title,.project-story-kicker{translate:none!important}\\n}\\n\\n/* Intro navigation: simple footer rhythm before the technical chapter. */\\n.project-story-actions{display:none!important}\\n.project-story-footer{grid-column:1/-1;display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:18px;margin-top:clamp(4px,1vw,10px);padding-top:20px;border-top:1px solid var(--project-line-soft,rgba(64,91,104,.14))}\\n.project-story-footer a{color:var(--project-body-grey,#849198)!important;font:500 9px/1.25 var(--sans);letter-spacing:.09em;text-transform:uppercase;text-decoration:none;transition:color 180ms ease,translate 260ms cubic-bezier(.22,1,.36,1)}\\n.project-story-footer a:hover,.project-story-footer a:focus-visible{color:var(--project-orange-hover,#ff9a63)!important;outline:none}\\n.project-story-home{justify-self:start}\\n.project-story-next{justify-self:end;text-align:right}\\n.project-story-scroll{justify-self:center;display:grid!important;justify-items:center;gap:7px;color:var(--project-heading-blue,#6a828d)!important;text-align:center}\\n.project-story-scroll .story-scroll-arrow{display:block;color:var(--project-orange,#FF7A32);font-size:20px;line-height:1;transition:translate 300ms cubic-bezier(.22,1,.36,1)}\\n.project-story-scroll:hover .story-scroll-arrow,.project-story-scroll:focus-visible .story-scroll-arrow{translate:0 4px}\\n@media(max-width:620px){.project-story-footer{grid-template-columns:1fr 1fr;align-items:start}.project-story-scroll{grid-column:1/-1;grid-row:1;justify-self:start;justify-items:start;margin-bottom:8px}.project-story-home{grid-column:1;grid-row:2}.project-story-next{grid-column:2;grid-row:2}}\\n\\n\\n/* A scroll chapter transition between the reflective intro and the existing technical page. */\\n.technical-chapter-handoff{\\n  --chapter-p:0;\\n  position:relative;\\n  left:50%;\\n  width:100vw;\\n  min-height:clamp(300px,48vh,470px);\\n  margin:clamp(18px,4vh,42px) 0 clamp(30px,5vh,58px) -50vw;\\n  display:grid;\\n  place-items:center;\\n  overflow:hidden;\\n  isolation:isolate;\\n  scroll-margin-top:0;\\n}\\n.technical-chapter-handoff::before{\\n  content:'';\\n  position:absolute;\\n  inset:0;\\n  z-index:-2;\\n  background:\\n    radial-gradient(720px 300px at 50% 48%,rgba(33,58,72,.18),transparent 72%),\\n    linear-gradient(180deg,#010305 0%,#02070b 52%,#010305 100%);\\n  transform:scaleY(calc(.055 + (var(--chapter-p) * .945)));\\n  transform-origin:center;\\n  box-shadow:inset 0 1px rgba(93,126,148,.10),inset 0 -1px rgba(93,126,148,.10);\\n  will-change:transform;\\n}\\n.technical-chapter-handoff::after{\\n  content:'';\\n  position:absolute;\\n  left:50%;\\n  top:50%;\\n  width:min(760px,72vw);\\n  height:1px;\\n  z-index:-1;\\n  background:linear-gradient(90deg,transparent,rgba(255,122,50,.50) 22%,rgba(93,126,148,.34) 78%,transparent);\\n  transform:translate(-50%,-50%) scaleX(calc(.08 + (var(--chapter-p) * .92)));\\n  transform-origin:center;\\n  will-change:transform;\\n}\\n.technical-chapter-inner{\\n  display:grid;\\n  justify-items:center;\\n  gap:12px;\\n  padding:28px;\\n  text-align:center;\\n  transform:translateY(calc((1 - var(--chapter-p)) * 34px));\\n  will-change:transform;\\n}\\n.technical-chapter-label{\\n  color:var(--project-heading-blue,#6a828d)!important;\\n  font:500 clamp(17px,1.7vw,23px)/1 var(--sans);\\n  letter-spacing:.12em;\\n  text-transform:uppercase;\\n}\\n.technical-chapter-arrow{\\n  color:var(--project-orange,#FF7A32);\\n  font:300 24px/1 var(--sans);\\n  transform:translateY(calc(var(--chapter-p) * 6px));\\n}\\n@media(max-width:620px){\\n  .technical-chapter-handoff{min-height:250px;margin-top:20px;margin-bottom:34px}\\n  .technical-chapter-handoff::after{width:84vw}\\n}\\n@media(prefers-reduced-motion:reduce){\\n  .technical-chapter-handoff{--chapter-p:1!important}\\n  .technical-chapter-handoff::before,.technical-chapter-handoff::after,.technical-chapter-inner,.technical-chapter-arrow{transform:none!important}\\n}\\n\\n\\n/* Intro footer stays quiet; the technical chapter only appears as the user naturally scrolls into it. */\\n.project-story-footer{grid-template-columns:1fr 1fr!important;align-items:end!important}\\n.project-story-home{justify-self:start!important}\\n.project-story-next{justify-self:end!important;text-align:right!important}\\n.project-story-scroll{display:none!important}\\n\\n/* Shorter, continuous chapter handoff: no empty half-screen and no duplicate arrows. */\\n.technical-chapter-handoff{\\n  --chapter-p:0;\\n  min-height:clamp(150px,22vh,210px)!important;\\n  margin:clamp(8px,1.8vh,16px) 0 clamp(24px,3.2vh,36px) -50vw!important;\\n}\\n.technical-chapter-handoff::before{\\n  opacity:var(--chapter-p);\\n  transform:scaleY(calc(.012 + (var(--chapter-p) * .988)))!important;\\n}\\n.technical-chapter-handoff::after{\\n  opacity:var(--chapter-p);\\n  transform:translate(-50%,-50%) scaleX(var(--chapter-p))!important;\\n}\\n.technical-chapter-inner{\\n  opacity:clamp(0,calc((var(--chapter-p) - .34) * 2.1),1);\\n  transform:translateY(calc((1 - var(--chapter-p)) * 18px))!important;\\n}\\n.technical-chapter-arrow{display:none!important}\\n.technical-chapter-label{font-size:clamp(14px,1.35vw,18px)!important;letter-spacing:.14em!important}\\n@media(max-width:620px){\\n  .project-story-footer{grid-template-columns:1fr 1fr!important}\\n  .project-story-home{grid-column:1!important;grid-row:1!important}\\n  .project-story-next{grid-column:2!important;grid-row:1!important}\\n  .technical-chapter-handoff{min-height:135px!important;margin-top:8px!important;margin-bottom:24px!important}\\n}\\n@media(prefers-reduced-motion:reduce){\\n  .technical-chapter-handoff::before,.technical-chapter-handoff::after,.technical-chapter-inner{opacity:1!important}\\n}\\n\\n:host{display:block;width:100%;--bg:#0b0707;--panel:#100c0c;--panel-soft:rgba(244,240,234,.026);--text:#f4f0ea;--muted:#aaa39a;--line:rgba(244,240,234,.30);--line-soft:rgba(244,240,234,.13);--accent-line:#123a5a;--accent-text:#6fa0c8;--paper:#f4f2ed;--display:\\\"Cormorant Garamond\\\",Georgia,serif;--sans:\\\"Inter\\\",\\\"Helvetica Neue\\\",Arial,sans-serif}\\n.overlay-wrap{min-height:0!important;height:auto!important;display:block!important;padding:22px!important;overflow:visible!important}\\n.summary-panel{height:auto!important;max-height:none!important;overflow:visible!important;margin:0 auto!important}\\n.background-context{display:none!important}\\n\";\n  root.appendChild(style);\n  const shell=document.createElement('div');\n  shell.innerHTML=\"<main class=\\\"overlay-wrap\\\">\\n<article aria-label=\\\"Wearable EMG and motion-sensing sleeve project summary\\\" class=\\\"summary-panel\\\">\\n<section aria-label=\\\"Project overview\\\" class=\\\"project-story-intro\\\">\\n<div class=\\\"project-story-copy\\\">\\n<p class=\\\"project-story-kicker\\\">Project Statement</p>\\n<h1 class=\\\"project-story-title\\\">Wearable EMG Sleeve</h1>\\n<p class=\\\"project-story-subtitle\\\">Personal Project \\u00b7 Wearable Sensing \\u00b7 Embedded Integration</p>\\n<p class=\\\"project-story-statement\\\">Pod pressure, electrode contact, and cable movement changed EMG quality, so I refined the mechanical packaging and sensor setup together while integrating EMG, motion sensing, and elbow-angle measurement into one wearable system.</p>\\n</div>\\n<figure class=\\\"project-story-visual\\\">\\n<div class=\\\"project-story-frame\\\" style=\\\"--story-fit:cover;--story-position:center 42%;--story-scale:1.03;--story-bg:transparent;\\\">\\n<img loading=lazy decoding=async alt=\\\"Wearable EMG and motion-sensing sleeve during use\\\" src=\\\"emg_photos/emg_wear1.jpeg\\\"/>\\n</div>\\n<figcaption class=\\\"project-story-caption\\\">Wearable EMG + motion-sensing sleeve</figcaption>\\n</figure>\\n<nav aria-label=\\\"Project overview navigation\\\" class=\\\"project-story-footer\\\">\\n<a class=\\\"project-story-home\\\" href=\\\"../../index.html\\\">\\u2190 Back home</a>\\n<a class=\\\"project-story-next\\\" href=\\\"../control_chamber/chamber.html\\\">Next project \\u2192<br/><span>Environmental Control Chamber</span></a>\\n</nav>\\n</section>\\n<section aria-label=\\\"Technical detail chapter\\\" class=\\\"technical-chapter-handoff\\\" id=\\\"technical-detail\\\">\\n<div class=\\\"technical-chapter-inner\\\">\\n<span class=\\\"technical-chapter-label\\\">Technical Detail</span>\\n</div>\\n</section>\\n<div class=\\\"panel-top\\\">\\n<h1>Wearable EMG Sleeve</h1>\\n\\n</div>\\n<p class=\\\"project-type\\\">\\n        Personal Project\\n      </p>\\n<p class=\\\"summary-intro\\\">\\n        I built a compression-sleeve prototype that records muscle activity and arm\\n        motion together during exercise. Three EMG channels, two IMUs, and a direct\\n        elbow-angle sensor feed a Bluetooth dashboard for comparing the signals during\\n        curls, extensions, and lateral raises. My work covered the sensing layout,\\n        wearable hardware, electrode mounting, calibration, and integrated testing.\\n      </p>\\n<section class=\\\"hero-card\\\">\\n<div aria-label=\\\"Integrated wearable system and live dashboard\\\" class=\\\"result-grid top-showcase\\\">\\n<article class=\\\"visual-card header-only\\\">\\n<div class=\\\"media-frame\\\">\\n<img loading=lazy decoding=async alt=\\\"Wearable EMG and motion-sensing sleeve worn during a biceps curl\\\" class=\\\"wearing-photo\\\" src=\\\"emg_photos/emg_wear.jpeg\\\"/>\\n</div>\\n<h3>Worn System</h3>\\n</article>\\n<article class=\\\"visual-card header-only\\\">\\n<div class=\\\"media-frame\\\">\\n<img loading=lazy decoding=async alt=\\\"Live exercise dashboard\\\" class=\\\"dashboard-image\\\" src=\\\"../../photos-main/dashboard_em.png\\\"/>\\n</div>\\n<h3>Live Dashboard</h3>\\n</article>\\n</div>\\n</section>\\n<section class=\\\"summary-grid\\\">\\n<section class=\\\"summary-card full\\\">\\n<h2 class=\\\"section-heading\\\">Project Overview</h2>\\n<div class=\\\"system-list\\\">\\n<div class=\\\"system-row\\\">\\n<strong>Exercise Tests</strong>\\n<span>\\n                I used biceps curls, triceps extensions, and lateral raises to compare\\n                muscle activity with elbow motion, arm orientation, and repetition timing.\\n              </span>\\n</div>\\n<div class=\\\"system-row\\\">\\n<strong>EMG</strong>\\n<span>\\n                Three BioAmp EXG Pill channels measuring biceps, triceps, and shoulder\\n                activity through separate electrode pairs with a shared reference near\\n                the elbow.\\n              </span>\\n</div>\\n<div class=\\\"system-row\\\">\\n<strong>Motion + Joint Angle</strong>\\n<span>\\n                A shoulder-mounted LSM6DS3TR-C and the elbow module's onboard IMU\\n                provide segment orientation, with a potentiometer on A3 measuring elbow\\n                flexion directly. These measurements are combined in the live dashboard\n                during exercise.\\n              </span>\\n</div>\\n<div class=\\\"system-row\\\">\\n<strong>Electrode Contact + Placement</strong>\\n<span>\\n                I used removable EMG pods to control electrode spacing and placement, then\\n                adjusted pod fit, contact pressure, and wire routing to keep the electrodes\\n                stable as the arm moved.\\n              </span>\\n</div>\\n<div class=\\\"system-row\\\">\\n<strong>Wearable Hardware</strong>\\n<span>\\n                Compression sleeve carrying the EMG pods, shoulder sensor, routed\\n                wiring, and an elbow module containing the controller, power hardware,\\n                and elbow-angle sensor.\\n              </span>\\n</div>\\n<div class=\\\"system-row\\\">\\n<strong>Processing + Output</strong>\\n<span>\\n                XIAO nRF52840 Sense sampling and processing the sensor inputs, tracking\\n                repetition phase, and sending the combined measurements over\\n                Bluetooth Low Energy to the live dashboard.\\n              </span>\\n</div>\\n</div>\\n</section>\\n<section class=\\\"summary-card full\\\">\\n<h2>Wearable Hardware</h2>\\n<p>\\n            The main electronics pod houses the controller and power hardware near the elbow,\\n            with flexible wiring running to the sensing pods positioned along the sleeve. The\\n            complete pod assembly attaches with sew-on snap fasteners, so it can be removed as\\n            one unit and repositioned between attachment points to suit different arm sizes and\\n            sensor locations.\\n          </p>\\n<div aria-label=\\\"shoulder, elbow, and elbow-angle details\\\" class=\\\"component-row\\\">\\n<article class=\\\"visual-card header-only\\\">\\n<div aria-label=\\\"Hover to compare the shoulder pod and shoulder mounting location\\\" class=\\\"swap-card\\\" tabindex=\\\"0\\\">\\n<div class=\\\"media-frame\\\">\\n<div class=\\\"swap-image\\\">\\n<img loading=lazy decoding=async alt=\\\"shoulder sensor pod\\\" class=\\\"default-image component-photo\\\" src=\\\"emg_photos/shoulderpod.png\\\"/>\\n<img loading=lazy decoding=async alt=\\\"shoulder sensor mounted on the sleeve\\\" class=\\\"hover-image component-photo\\\" src=\\\"emg_photos/shoulder.png\\\"/>\\n</div>\\n</div>\\n</div>\\n<h3>Shoulder Pod</h3>\\n</article>\\n<article class=\\\"visual-card header-only\\\">\\n<div aria-label=\\\"Hover to compare the biceps EMG pod CAD views\\\" class=\\\"swap-card\\\" tabindex=\\\"0\\\">\\n<div class=\\\"media-frame\\\">\\n<div class=\\\"swap-image\\\">\\n<img loading=lazy decoding=async alt=\\\"Biceps EMG pod exterior CAD view\\\" class=\\\"default-image component-photo\\\" src=\\\"emg_photos/bicep.png\\\"/>\\n<img loading=lazy decoding=async alt=\\\"Biceps EMG pod interior CAD view\\\" class=\\\"hover-image component-photo\\\" src=\\\"emg_photos/bicepw.png\\\"/>\\n</div>\\n</div>\\n</div>\\n<h3>Biceps / Triceps Pod</h3>\\n</article>\\n<article class=\\\"visual-card header-only\\\">\\n<div aria-label=\\\"Hover to compare the potentiometer cap and elbow-angle potentiometer\\\" class=\\\"swap-card\\\" tabindex=\\\"0\\\">\\n<div class=\\\"media-frame\\\">\\n<div class=\\\"swap-image\\\">\\n<img loading=lazy decoding=async alt=\\\"elbow-angle potentiometer and mechanical interface\\\" class=\\\"default-image component-photo\\\" src=\\\"emg_photos/potentiometer.png\\\"/>\\n<img loading=lazy decoding=async alt=\\\"Protective cap for the elbow-angle potentiometer\\\" class=\\\"hover-image component-photo\\\" src=\\\"emg_photos/potencap.png\\\"/>\\n</div>\\n</div>\\n</div>\\n<h3>Elbow-Angle Sensor Cap</h3>\\n</article>\\n</div>\\n<p class=\\\"hardware-separator-copy\\\">\\n            Early concepts used gold-plated PCB-style contact pieces, but the pod design moved\\n            toward flexible TPU and rounded contact surfaces so the interface could follow the\\n            sleeve and distribute pressure more evenly. The final geometry keeps each electrode\\n            pair about 2 cm apart, with removable caps holding the contacts in place. A fixed\\n            reference electrode near the elbow gives a consistent location with less movement,\\n            while the wire routing keeps cable motion away from the electrode sites.\\n          </p>\\n<div aria-label=\\\"electronics and sleeve integration details\\\" class=\\\"hardware-grid\\\">\\n<article class=\\\"visual-card header-only electronics-card\\\">\\n<div class=\\\"media-frame\\\">\\n<img loading=lazy decoding=async alt=\\\"Electronics pod open for inspection and adjustment\\\" class=\\\"electronics-photo\\\" src=\\\"emg_photos/open_pod.jpeg\\\"/>\\n</div>\\n<h3>Electronics Packaging</h3>\\n</article>\\n<article class=\\\"visual-card header-only\\\">\\n<div class=\\\"media-frame\\\">\\n<img loading=lazy decoding=async alt=\\\"Full wearable sensing sleeve assembly\\\" class=\\\"sleeve-photo\\\" src=\\\"emg_photos/full_sleeve.jpeg\\\"/>\\n</div>\\n<h3>Sleeve Integration</h3>\\n</article>\\n</div>\\n</section>\\n<section class=\\\"summary-card full\\\">\\n<h2>Testing</h2>\\n<p>\\n            Testing started with each sensor independently before moving into full exercise\\n            trials. This exposed channel-mapping and intermittent IMU issues and showed how\\n            strongly EMG quality changed with electrode pressure and cable movement.\\n          </p>\\n<p>\\n            I corrected the channel mapping and IMU configuration so EMG, orientation, and\\n            elbow angle could stream together during movement. The current version still shows\\n            a slight delay between motion and the dashboard response, along with noticeable noise\\n            in the EMG signals.\\n          </p>\\n<div aria-label=\\\"Integrated exercise demonstration\\\" class=\\\"final-test-grid video-only\\\">\\n<article class=\\\"visual-card header-only demo-video-card\\\">\\n<div class=\\\"media-frame\\\">\\n<video autoplay=\\\"\\\" controls=\\\"\\\" loop=\\\"\\\" muted=\\\"\\\" playsinline=\\\"\\\" poster=\\\"emg_photos/comp_arm.jpeg\\\" preload=\\\"metadata\\\">\\n<source src=\\\"emg_photos/emg_vid.mp4\\\" type=\\\"video/mp4\\\"/>\\n</video>\\n<img loading=lazy decoding=async alt=\\\"Integrated exercise demonstration\\\" class=\\\"pdf-video-poster\\\" src=\\\"emg_photos/comp_arm.jpeg\\\"/>\\n</div>\\n<h3>Integrated Exercise Test</h3>\\n</article>\\n</div>\\n</section>\\n</section>\\n<footer aria-label=\\\"Project navigation\\\" class=\\\"project-footer\\\">\\n<a class=\\\"all-projects-link\\\" href=\\\"../../index.html\\\">\\n<span aria-hidden=\\\"true\\\">\\u2190</span>\\n<span>Back to all projects</span>\\n</a>\\n<a class=\\\"next-project-link\\\" href=\\\"../control_chamber/chamber.html\\\">\\n<span class=\\\"next-project-label\\\">Next project</span>\\n<span class=\\\"next-project-title\\\">Environmental Control Chamber</span>\\n</a>\\n</footer>\\n</article>\\n</main>\";\n  while(shell.firstChild) root.appendChild(shell.firstChild);\n  root.querySelectorAll('video').forEach(video=>{\n    video.muted=true; video.defaultMuted=true; video.volume=0;\n    if(video.hasAttribute('autoplay')){video.loop=true; video.playsInline=true; const p=video.play(); if(p) p.catch(()=>{});}\n  });\n})();"]});